package com.hbm.client.solarboiler;
import com.google.gson.*;import com.hbm.machine.solarboiler.SolarBoilerContent;import net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.fml.event.lifecycle.FMLClientSetupEvent;import net.neoforged.fml.loading.FMLPaths;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.client.extensions.common.*;import java.nio.file.*;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)
public final class SolarBoilerClient {
 private static int beamLimit=250;public static int beamLimit(){return beamLimit;}
 @SubscribeEvent public static void models(ModelEvent.ModifyBakingResult event){event.getModels().replaceAll((id,model)->id.id().equals(SolarBoilerContent.BEAM.getId())?new SteelBeamModel(model,id.getVariant().equals("inventory"),event.getTextureGetter()):id.id().equals(SolarBoilerContent.MIRROR.getId())&&!id.getVariant().equals("inventory")?new SolarMirrorModel(model,event.getTextureGetter()):model);}
 @SubscribeEvent public static void renderer(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(SolarBoilerContent.BOILER_BE.get(),SolarBoilerRenderer::new);}
 @SubscribeEvent public static void extensions(RegisterClientExtensionsEvent event){event.registerItem(new IClientItemExtensions(){private SolarBoilerItemRenderer renderer;@Override public BlockEntityWithoutLevelRenderer getCustomRenderer(){return renderer==null?(renderer=new SolarBoilerItemRenderer()):renderer;}},SolarBoilerContent.BOILER_ITEM.get(),SolarBoilerContent.MIRROR_ITEM.get());}
 @SubscribeEvent public static void setup(FMLClientSetupEvent event){event.enqueueWork(()->{var path=FMLPaths.CONFIGDIR.get().resolve("hbmConfig/hbmClient.json");try{Files.createDirectories(path.getParent());var values=Files.isRegularFile(path)?JsonParser.parseString(Files.readString(path)).getAsJsonObject():new JsonObject();if(values.has("RENDER_HELIOSTAT_BEAM_LIMIT"))beamLimit=values.get("RENDER_HELIOSTAT_BEAM_LIMIT").getAsInt();values.addProperty("RENDER_HELIOSTAT_BEAM_LIMIT",beamLimit);Files.writeString(path,new GsonBuilder().setPrettyPrinting().create().toJson(values)+"\n");}catch(Exception error){com.mojang.logging.LogUtils.getLogger().error("Cannot load original heliostat beam limit",error);}});}
}
